int nCr(int n, int r) {
    if (n < r)
        return 0;

    if (r == 0 || r == n)
        return 1;

    if (r > n - r) {
        r = n - r;
    }

    long long result = 1;
    for (int i = 1; i <= r; ++i) {
        result = result * (n - i + 1) / i;
    }

    return static_cast<int>(result);
}

