int power_rec(int base, int exp, int mod) {
    int res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            res = (static_cast<long long>(res) * base) % mod;
        }
        base = (static_cast<long long>(base) * base) % mod;
        exp >>= 1;
    }
    return res;
}

