void backtrack(int low, int high, int start, vector<int>& result) {
    while (start != 9) {
        if (start % 10 < 9) {
            start = start * 10 + (start % 10) + 1;
            if (start >= low && start <= high) {
                result.push_back(start);
            }
        } else {
            int num_digits = log10(start);
            int MSD = start / pow(10, num_digits);
            start = MSD + 1;
        }
    }
}

