double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
    // Replace direct self-recursion (tail call when nums1.size() > nums2.size()) with an iterative loop
    vector<int>* p1 = &nums1;
    vector<int>* p2 = &nums2;

    while (p1->size() > p2->size()) {
        std::swap(p1, p2);
    }

    int m = p1->size();
    int n = p2->size();

    int low = 0, high = m;
    while (low <= high) {
        int Px = low + (high - low) / 2;
        int Py = (m + n + 1) / 2 - Px;

        int x1 = (Px == 0) ? INT_MIN : (*p1)[Px - 1];
        int x3 = (Px == m) ? INT_MAX : (*p1)[Px];

        int x2 = (Py == 0) ? INT_MIN : (*p2)[Py - 1];
        int x4 = (Py == n) ? INT_MAX : (*p2)[Py];

        if (x1 <= x4 && x2 <= x3) {
            if ((m + n) % 2 == 0)
                return (max(x1, x2) + min(x3, x4)) / 2.0;

            return max(x1, x2);
        } else if (x1 > x4) {
            high = Px - 1;
        } else {
            low = Px + 1;
        }
    }

    return -1;
}

