int solve(int n, int p) {
    // Using an explicit std::stack to simulate the binary tree recursion
    // without using actual function self-recursion.
    #include <stack>
    #include <cmath>

    struct State {
        int n;
        int p;
    };

    std::stack<State> st;
    st.push({n, p});

    while (!st.empty()) {
        State current = st.top();
        st.pop();

        if (current.n == 0) {
            return true;
        }

        if (std::pow(3, current.p) > current.n) {
            continue;
        }

        // Push right branch first so left branch is processed first
        st.push({current.n, current.p + 1});
        st.push({current.n - static_cast<int>(std::pow(3, current.p)), current.p + 1});
    }

    return false;
}

