void dfs(std::vector<int> &arr, int i, std::vector<int> &ans, int stn)
{
  struct Frame {
    int i;
    int stn;
    int stage;
  };

  std::stack<Frame> s;
  s.push({i, stn, 0});

  while (!s.empty()) {
    Frame &curr = s.top();

    if (curr.i == static_cast<int>(arr.size())) {
      ans.push_back(curr.stn);
      s.pop();
      continue;
    }

    if (curr.stage == 0) {
      curr.stage = 1;
      s.push({curr.i + 1, curr.stn, 0});
    } else if (curr.stage == 1) {
      curr.stage = 2;
      s.push({curr.i + 1, curr.stn + arr[curr.i], 0});
    } else {
      s.pop();
    }
  }
}

