void findmax(string str, string &ans, int k, int n, int i)
{
  if (k == 0)
    return;

  char maxs = str[i];

  for (int j = i + 1; j < n; j++)
  {
    maxs = max(maxs, str[j]);
  }

  if (maxs != str[i])
    k--;
  for (int j = i; j < n; j++)
  {
    if (str[j] == maxs)
    {
      swap(str[i], str[j]);
      ans = max(ans, str);
      findmax(str, ans, k, n, i + 1);
      swap(str[i], str[j]);
    }
  }
  return;
}

