void findmax(string str, string &ans, int k, int n, int i) {
  struct State {
    string str;
    int k;
    int i;
    int j;
    char maxs;
    bool initialized;
    bool second_loop;
  };

  if (k == 0)
    return;

  std::stack<State> stk;
  stk.push({str, k, i, i + 1, '\0', false, false});

  while (!stk.empty()) {
    State &curr = stk.top();

    if (curr.k == 0) {
      stk.pop();
      continue;
    }

    if (!curr.initialized) {
      curr.maxs = curr.str[curr.i];
      curr.j = curr.i + 1;
      curr.initialized = true;
    }

    if (curr.j < n) {
      curr.maxs = max(curr.maxs, curr.str[curr.j]);
      curr.j++;
      continue;
    }

    if (!curr.second_loop) {
      if (curr.maxs != curr.str[curr.i])
        curr.k--;
      curr.j = curr.i;
      curr.second_loop = true;
    }

    if (curr.j < n) {
      if (curr.str[curr.j] == curr.maxs) {
        swap(curr.str[curr.i], curr.str[curr.j]);
        ans = max(ans, curr.str);

        string next_str = curr.str;
        int next_k = curr.k;
        int next_i = curr.i + 1;

        swap(curr.str[curr.i], curr.str[curr.j]);

        if (next_k > 0) {
          stk.push({next_str, next_k, next_i, next_i + 1, '\0', false, false});
          curr.j++;
          continue;
        }
      }
      curr.j++;
      continue;
    }

    stk.pop();
  }
}

