char findKthBit(int n, int k) {
    bool inverted = false;

    while (n > 1) {
        int length = (1 << n) - 1;
        int mid = length / 2 + 1; // equivalent to ceil(length / 2.0)

        if (k < mid) {
            // Stay in the left half, arguments update normally
            n = n - 1;
        } else if (k == mid) {
            // Middle element is always '1' before inversion
            return inverted ? '0' : '1';
        } else {
            // Right half: mirror position and toggle inversion state
            k = length - (k - 1);
            n = n - 1;
            inverted = !inverted;
        }
    }

    // Base case: n == 1, returns '0'
    char ch = '0';
    return inverted ? (ch == '0' ? '1' : '0') : ch;
}

