int longest_palindromic_substr(string str) {
    int n = str.length();
    if (n == 0) return 0;

    // dp[i][j] stores the length of the longest palindromic substring in str[i...j]
    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int i = 0; i < n; ++i) {
        dp[i][i] = 1;
    }

    int max_len = 1;

    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i <= n - len; ++i) {
            int j = i + len - 1;
            if (str[i] == str[j]) {
                if (len == 2) {
                    dp[i][j] = 2;
                } else {
                    dp[i][j] = dp[i + 1][j - 1] + 2;
                }
            } else {
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
            }
            max_len = max(max_len, dp[i][j]);
        }
    }

    return max_len;
}

