void get_option_states(const vector<int>& options, int index, int k, int state,
                           vector<int>& res){

        struct Frame {
            int index;
            int k;
            int state;
            int i;
        };

        if (k == 0) {
            res.push_back(state);
            return;
        }
        if (index == options.size()) return;

        std::stack<Frame> st;
        // Push the initial state for the loop starting at 'index'
        st.push({index, k, state, index});

        while (!st.empty()) {
            auto& frame = st.top();

            if (frame.i >= options.size()) {
                st.pop();
                if (!st.empty()) {
                    st.top().i++;
                }
                continue;
            }

            int next_k = frame.k - 1;
            int next_state = frame.state | (1 << options[frame.i]);

            if (next_k == 0) {
                res.push_back(next_state);
                frame.i++;
            } else if (frame.i + 1 < options.size()) {
                // Instead of recursive call, push the new frame onto the stack
                st.push({frame.i + 1, next_k, next_state, frame.i + 1});
            } else {
                frame.i++;
            }
        }
