void grayCodeUtil(vector<int>& res, int n, int& num) {
    // Iterative approach replacing direct multi-branch recursion
    // using an explicit stack to track traversal state (n and execution phase).
    struct Frame {
        int n;
        int phase;
    };

    vector<Frame> stack;
    stack.push_back({n, 0});

    while (!stack.empty()) {
        Frame& current = stack.back();

        if (current.n == 0) {
            res.push_back(num);
            stack.pop_back();
        } else if (current.phase == 0) {
            current.phase = 1;
            stack.push_back({current.n - 1, 0});
        } else if (current.phase == 1) {
            num = num ^ (1 << (current.n - 1));
            current.phase = 2;
            stack.push_back({current.n - 1, 0});
        } else {
            stack.pop_back();
        }
    }
}

