        if (rem_k == 0) return 1;
        if (dp[rem_n][rem_k] != -1) {
            return dp[rem_n][rem_k];
        }

        long long ways = 0;
        int curr_val = (rem_k < 31 && (1 << rem_k) <= rem_n) ? (1 << rem_k) : n + 1;

        if (rem_n >= curr_val) {
            ways = self(self, rem_n - curr_val, rem_k) + self(self, rem_n, rem_k - 1);
        } else {
            ways = self(self, rem_n, rem_k - 1);
        }

        return dp[rem_n][rem_k] = ways;
    };

    return solve(solve, n, k);
}

