int countSeq(int n, int diff) {
    if (abs(diff) > n) return 0;
    if (n == 1 && diff == 0) return 2;
    if (n == 1 && abs(diff) == 1) return 1;

    // The original recursive function computes a tree-like recursion where
    // each step branches into 3 recursive calls: countSeq(n-1, diff+1), 
    // countSeq(n-1, diff), and countSeq(n-1, diff-1).
    // Converting this to an iterative approach requires dynamic programming 
    // or maintaining the state of the tree traversal using a stack. 
    // Since the recursion branches, an explicit stack is required to track 
    // the states (n, diff) that need to be processed.

    int total_res = 0;
    std::stack<std::pair<int, int>> st;
    st.push({n, diff});

    while (!st.empty()) {
        auto [curr_n, curr_diff] = st.top();
        st.pop();

        if (abs(curr_diff) > curr_n) {
            continue;
        }
        if (curr_n == 1 && curr_diff == 0) {
            total_res += 2;
            continue;
        }
        if (curr_n == 1 && abs(curr_diff) == 1) {
            total_res += 1;
            continue;
        }

        // Push the three branches onto the stack
        st.push({curr_n - 1, curr_diff + 1});
        st.push({curr_n - 1, curr_diff});
        st.push({curr_n - 1, curr_diff}); // coefficient of 2
        st.push({curr_n - 1, curr_diff - 1});
    }

    return total_res;
}

