bool isWinning(int pos) {
  if (pos <= 0)
    return false;

  // Using a bottom-up iterative approach with a vector (or fixed array since max pos is likely bounded,
  // but a vector handles arbitrary positive integers safely and efficiently).
  // Since the recurrence only depends on pos - 1, pos - 3, and pos - 4, we can compute iteratively.
  if (pos < 0) return false;

  // To avoid large memory allocation if `pos` is very large, we can compute DP values sequentially.
  // However, since we need up to `pos`, a dynamic vector is standard.
  std::vector<bool> dp(pos + 1, false);

  int moves[3] = { 1, 3, 4 };
  for (int i = 1; i <= pos; ++i) {
    for (int m : moves) {
      if (i >= m && !dp[i - m]) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[pos];
}

