    double epsilon = 1e-12;

    while (l <= r) {
        double mid = (l + r) / 2;
        if (mid * mid > a) {
            r = mid;
        } else {
            if (a - mid * mid < epsilon) {
                double result = mid;
                while (inversion_count > 0) {
                    result = 1 / result;
                    inversion_count--;
