// Improved code replacing direct self-recursion with an iterative loop.
// Since the original recursion is tree-like (multi-branch branching at each step),
// we use an explicit std::stack to manage the DFS traversal state without deep recursion.

#include <stack>

int countSolutions(int n, int val) {
    int total = 0;

    // Using a stack to store the state {n, val} for iterative DFS traversal
    std::stack<std::pair<int, int>> stk;
    stk.push({n, val});

    while (!stk.empty()) {
        auto [current_n, current_val] = stk.top();
        stk.pop();

        if (current_n == 1) {
            if (current_val >= 0) {
                total += 1;
            }
            continue;
        }

        for (int i = 0; i <= current_val; ++i) {
            stk.push({current_n - 1, current_val - i});
        }
    }

    return total;
}

