void checkUntil(int startNum, int K, int initialN, vector<int>& ans) {
    struct State {
        int num;
        int N;
        int branch;
    };

    stack<State> st;
    st.push({startNum, initialN, 0});

    while (!st.empty()) {
        State& current = st.top();

        if (current.N == 1) {
            ans.push_back(current.num);
            st.pop();
            continue;
        }

        int rem = current.num % 10;

        if (current.branch == 0) {
            current.branch = 1;
            if (rem + K <= 9) {
                st.push({10 * current.num + (rem + K), current.N - 1, 0});
                continue;
            }
        }

        if (current.branch == 1) {
            current.branch = 2;
            if (K != 0) {
                if (rem - K >= 0) {
                    st.push({10 * current.num + (rem - K), current.N - 1, 0});
                    continue;
                }
            }
        }

        st.pop();
    }
}

