#include <string>
#include <map>
#include <stack>

using namespace std;

vector<int> graph[100];
vector<string> weight(100);

bool Pangram(string x) {
    map<char, int> mp;
    int n = x.size();
    for (int i = 0; i < n; i++) mp[x[i]]++;
    if (mp.size() == 26) return true;
    else return false;
}

int countTotalPangram(int n) {
    int cnt = 0;
    for (int i = 1; i <= n; i++) if (Pangram(weight[i])) cnt++;
    return cnt;
}

void dfs(int start_node, int start_parent) {
    // Frame structure to simulate call stack for post-order processing
    struct Frame {
        int node;
        int parent;
        size_t child_idx;
        bool visited_children;
    };

    stack<Frame> stk;
    stk.push({start_node, start_parent, 0, false});

    while (!stk.empty()) {
        Frame& curr = stk.top();

        if (!curr.visited_children) {
            curr.visited_children = true;
            for (int to : graph[curr.node]) {
                if (to == curr.parent) continue;
                // Push children onto the stack
                stk.push({to, curr.node, 0, false});
            }
        } else {
            // After all children are processed (post-order equivalent),
            // aggregate weights to the parent if there is one on the stack below.
            int finished_node = curr.node;
            int curr_parent = curr.parent;
            stk.pop();

            if (!stk.empty()) {
                // The new top is the parent (or ancestor) that called us
                weight[stk.top().node] += weight[finished_node];
            }
        }
    }
}

