    // without an explicit stack or queue to manage the traversal state.
    // As instructed ("use an explicit std::stack or std::queue only when traversal state really needs it"),
    // we use a stack to replace the recursive calls.

    struct State {
        int pos;
        int prev;
        int left;
        int i;
        int answer;
        int stage; // To track progress past the loop
    };

    int total_answer = 0;
    stack<State> s;
    s.push({pos, prev, left, prev, 0, 0});

    while (!s.empty()) {
        auto& current = s.top();

        if (current.pos == k) {
            int ret = (current.left == 0) ? 1 : 0;
            s.pop();
            if (!s.empty()) {
                s.top().answer += ret;
            } else {
                total_answer += ret;
            }
            continue;
        }

        if (current.left == 0) {
            int ret = 0;
            s.pop();
            if (!s.empty()) {
                s.top().answer += ret;
            } else {
                total_answer += ret;
            }
            continue;
        }

        if (current.i <= current.left) {
            int next_pos = current.pos + 1;
            int next_prev = current.i;
            int next_left = current.left - current.i;

            // Increment i for the next iteration of the loop
            current.i++;

            // Push child state
            s.push({next_pos, next_prev, next_left, next_prev, 0, 0});
        } else {
            int ret = current.answer;
            s.pop();
            if (!s.empty()) {
                s.top().answer += ret;
            } else {
                total_answer += ret;
            }
        }
    }

    return total_answer;
}

