void lexicographicallySmall(Node* root, string s, string& finalAns) {
    if (root == nullptr) return;

    // Using an explicit stack to replace recursion while maintaining traversal state
    std::stack<std::pair<Node*, string>> st;
    st.push({root, s});

    while (!st.empty()) {
        auto [curr, currentS] = st.top();
        st.pop();

