int solve(int n) {
    if (n < 0) return 0;
    if (n == 0) return 1;

    std::vector<int> dp(n + 1, 0);
    dp[0] = 1;

    for (int i = 1; i <= n; ++i) {
        int res = 0;
        if (i - 1 >= 0) res += dp[i - 1];
        if (i - 3 >= 0) res += dp[i - 3];
