int64_t gcdExtended(const int64_t& a, const int64_t& b, int64_t& x,
                    int64_t& y) {
    int64_t current_a = a;
    int64_t current_b = b;

    // We need to keep track of the steps to compute x and y after the loop.
    // Since it's a linear recursion, we can store the sequence of (b / a) values
    // or use a stack. Alternatively, compute iteratively from the bottom up,
    // or use an explicit stack to simulate the call stack.

    std::stack<std::pair<int64_t, int64_t>> call_stack;

    while (current_a != 0) {
        call_stack.push({current_a, current_b});
        int64_t next_a = current_b % current_a;
        int64_t next_b = current_a;
        current_a = next_a;
        current_b = next_b;
    }

    int64_t gcd = current_b;
    x = 0;
    y = 1;

    while (!call_stack.empty()) {
        auto [curr_a, curr_b] = call_stack.top();
        call_stack.pop();

        int64_t x1 = x;
        int64_t y1 = y;

        x = y1 - (curr_b / curr_a) * x1;
        y = x1;
    }

    return gcd;
}

