string commonPrefix(string arr[], int low, int high) {
    if (low > high) return "";

    // Iterative divide-and-conquer using an explicit stack to eliminate recursion
    struct Task {
        int low;
        int high;
        int state; // 0: initial, 1: after left, 2: after right
        string res1;
        string res2;
    };

    std::stack<Task> s;
    s.push({low, high, 0, "", ""});
    string final_result = "";

    while (!s.empty()) {
        Task& current = s.top();

        if (current.low == current.high) {
            final_result = arr[current.low];
            s.pop();
            continue;
        }

        int mid = current.low + (current.high - current.low) / 2;

        if (current.state == 0) {
            current.state = 1;
            s.push({current.low, mid, 0, "", ""});
        } else if (current.state == 1) {
            current.res1 = final_result;
            current.state = 2;
            s.push({mid + 1, current.high, 0, "", ""});
        } else {
            current.res2 = final_result;
            final_result = commonPrefixUtil(current.res1, current.res2);
            s.pop();
        }
    }

    return final_result;
}

