int maxUncrossedLines(vector<int>& A, vector<int>& B) {
    // Replace self-recursion with an iterative loop to swap inputs if A is smaller
    vector<int>* pA = &A;
    vector<int>* pB = &B;
    if (pA->size() < pB->size()) {
        std::swap(pA, pB);
    }

    vector<vector<int>> dp(2, vector<int>(pB->size() + 1));
    for (size_t i = 0; i < pA->size(); ++i) {
        for (size_t j = 0; j < pB->size(); ++j) {
            dp[(i + 1) % 2][j + 1] = max(dp[i % 2][j] + static_cast<int>((*pA)[i] == (*pB)[j]),
                                         max(dp[i % 2][j + 1], dp[(i + 1) % 2][j]));
        }
    }
    return dp[pA->size() % 2][pB->size()];
}

