using namespace std;

int countSortedArrays(int start, int m, int size, int n) {
    // This is equivalent to finding the number of combinations with repetition, 
    // or combinations of (n - start + 1) elements taken in (m - size) slots.
    // Since the original function uses a branching recursion, converting it cleanly 
    // via an iterative loop while maintaining identical semantics can be achieved 
    // using dynamic programming or a memoized/combinatorial approach.
    // Here we implement an iterative DP / combinatorial lookup to avoid recursion completely.

    int lengthToFill = m - size;
    int availableElements = n - start + 1;

    if (lengthToFill < 0) return 0;
    if (lengthToFill == 0) return 1;
    if (availableElements <= 0) return 0;

    // Using a 2D table for iterative DP to mimic the exact state space without recursion
    // rows: size from 0 to m
    // cols: start from 1 to n+1
    // To keep memory O(N), we can use a rolling vector or direct combinatorial math.
    // Given constraints aren't explicitly known, a DP table of size (m+1) x (n+2) is safe.

    // Let's use an explicit stack to strictly replace the self-recursion structure as requested,
    // or an equivalent iterative tabulation if applicable. Since it's a binary tree recursion
    // (taken + notTaken), an explicit std::stack storing states is the most direct literal conversion.

    #include <stack>
    struct State {
        int start;
        int size;
    };

    int total_count = 0;
    std::stack<State> stk;
    stk.push({start, size});

    while (!stk.empty()) {
        State curr = stk.top();
        stk.pop();

        if (curr.size == m) {
            total_count += 1;
            continue;
        }
        if (curr.start > n) {
            continue;
        }

        // Branch 2: notTaken (start + 1, size)
        stk.push({curr.start + 1, curr.size});
        // Branch 1: taken (start, size + 1)
        stk.push({curr.start, curr.size + 1});
    }

    return total_count;
}

