#include <algorithm>

void mergesort(std::vector<int> &arr, int low, int high)
{
    if (low >= high) {
        return;
    }

    // Bottom-up (iterative) merge sort to completely eliminate recursion
    int n = arr.size();
    if (n <= 1) return;

    for (int curr_size = 1; curr_size <= high - low; curr_size = 2 * curr_size) {
        for (int left_start = low; left_start < high; left_start += 2 * curr_size) {
            int mid = std::min(left_start + curr_size - 1, high);
            int right_end = std::min(left_start + 2 * curr_size - 1, high);

            // In-place merge equivalent to the original merge step
            if (mid < right_end) {
                std::inplace_merge(arr.begin() + left_start, arr.begin() + mid + 1, arr.begin() + right_end + 1);
            }
        }
    }
}

