int lps(char* seq, int i, int j) {
    if (i > j) return 0;
    int n = strlen(seq);
    if (n == 0) return 0;

    // Using a dynamic programming table sized dynamically from the argument length
    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int idx = 0; idx < n; idx++) {
        dp[idx][idx] = 1;
    }

    for (int cl = 2; cl <= n; cl++) {
        for (int i = 0; i < n - cl + 1; i++) {
            int j = i + cl - 1;
            if (seq[i] == seq[j] && cl == 2) {
                dp[i][j] = 2;
            } else if (seq[i] == seq[j]) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j]);
            }
        }
    }

    return dp[i][j];
}

