#include <iostream>

using namespace std;

int Hosoya(int n, int m) {
    if (n < 0 || m < 0 || m > n) return 0;

    // Memoization table sized dynamically based on arguments (n+1 by m+1)
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, -1));

    auto solve = [&](auto& self, int i, int j) -> int {
        if ((i == 0 && j == 0) || (i == 1 && j == 0) || (i == 1 && j == 1) || (i == 2 && j == 1)) return 1;
        if (j > i || i < 0 || j < 0) return 0;
        if (dp[i][j] != -1) return dp[i][j];

        if (i > j) {
            dp[i][j] = self(self, i - 1, j) + self(self, i - 2, j);
        } else if (j == i) {
            dp[i][j] = self(self, i - 1, j - 1) + self(self, i - 2, j - 2);
        } else {
            dp[i][j] = 0;
        }
        return dp[i][j];
    };

    return solve(solve, n, m);
}

