long long ExtendedEuclidAlgo(long long a, long long b, long long& x, long long& y) {
    long long x_prev = 1, y_prev = 0;
    long long x_curr = 0, y_curr = 1;

    while (b != 0) {
        long long q = a / b;
        long long temp_a = b;
        b = a % b;
        a = temp_a;

        long long temp_x = x_curr;
        x_curr = x_prev - q * x_curr;
        x_prev = temp_x;

        long long temp_y = y_curr;
        y_curr = y_prev - q * y_curr;
        y_prev = temp_y;
    }

    x = x_prev;
    y = y_prev;
