void perm(int i, int n, int vis[], int cur[])
{
    // Since the recursion branches heavily in a loop, converting it to a purely
    // iterative approach without a stack would require complex state tracking.
    // However, we can use an explicit stack to manage the DFS state (level i and loop index j)
    // to completely eliminate self-recursion while keeping the signature identical.

    #include <stack>

    struct State {
        int i;
        int j;
    };

    std::stack<State> stk;
    stk.push({i, 0});

    while (!stk.empty()) {
        State& current = stk.top();

        if (current.i == n) {
            // print
            stk.pop();
            if (!stk.empty()) {
                // Backtrack: unvisit the element we placed at i - 1
                vis[stk.top().j - 1] = 0;
            }
            continue;
        }

        if (current.j < n) {
            int j = current.j;
            current.j++; // Advance for the next iteration of the loop

            if (!vis[j]) {
                vis[j] = 1;
                cur[current.i] = j;
                stk.push({current.i + 1, 0});
            }
        } else {
            stk.pop();
            if (!stk.empty()) {
                // Backtrack: unvisit the element we placed at the previous level
                vis[stk.top().j - 1] = 0;
            }
        }
    }
}

