using namespace std;

int countNumbers(int x, int n) {
    if (x > n) return 0;

    // The number of states is bounded by n. However, x grows multiplicatively (x * 10 + d).
    // Since x can exceed n, we can use a dynamic programming / memoization approach
    // or simply recognize that this function computes a trie of numbers formed by digits 0 and 1.
    // Given the constraints and typical values for such competitive programming problems,
    // we can memoize based on the value of x.
    // Since we need to size any table from the arguments rather than a fixed constant,
    // and x can be up to n, we can use a hash map or a vector of size n + 1 (if x <= n).

    if (x > n) return 0;

    // For large n, a flat vector of size n+1 works if n is reasonably small, 
    // but to be safe with memory while sizing from arguments:
    vector<int> memo(n + 1, -1);

    auto solve = [&](auto& self, int curr) -> int {
        if (curr > n) return 0;
        if (curr <= n && memo[curr] != -1) return memo[curr];

        int res = 1;
        // Prevent potential overflow during multiplication before checking bounds
        if (curr <= n / 10) {
            res += self(self, curr * 10);
        }
        if (curr <= (n - 1) / 10) {
            res += self(self, curr * 10 + 1);
        }

        if (curr <= n) {
            memo[curr] = res;
        }
        return res;
    };

    return solve(solve, x);
}

