#include <vector>
#include <algorithm>

int BinomialCoefficient(int n, int k) {
  if (n < k) {
    return 0;
  }
  if (k == 0 || k == n) {
    return 1;
  }

  // k can be optimized due to symmetry: C(n, k) == C(n, n - k)
  k = std::min(k, n - k);

  // Use a 1D or 2D DP table sized dynamically from arguments n and k
  std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, 0));

  for (int i = 0; i <= n; ++i) {
    int max_j = std::min(i, k);
    for (int j = 0; j <= max_j; ++j) {
      if (j == 0 || j == i) {
        dp[i][j] = 1;
      } else {
        dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
      }
    }
  }

  return dp[n][k];
}

