int countSubstrs(string str, int i, int j, int n) {
    struct Frame {
        int i;
        int j;
        int n;
        int stage;
        int r1;
        int r2;
        int r3;
    };

    if (n == 1) return 1;
    if (n <= 0) return 0;

    stack<Frame> s;
    s.push({i, j, n, 0, 0, 0, 0});
    int final_result = 0;

    while (!s.empty()) {
        Frame& f = s.top();

        if (f.n == 1) {
            final_result = 1;
            s.pop();
            continue;
        }
        if (f.n <= 0) {
            final_result = 0;
            s.pop();
            continue;
        }

        if (f.stage == 0) {
            f.stage = 1;
            s.push({f.i + 1, f.j, f.n - 1, 0, 0, 0, 0});
        } else if (f.stage == 1) {
            f.r1 = final_result;
            f.stage = 2;
            s.push({f.i, f.j - 1, f.n - 1, 0, 0, 0, 0});
        } else if (f.stage == 2) {
            f.r2 = final_result;
            f.stage = 3;
            s.push({f.i + 1, f.j - 1, f.n - 2, 0, 0, 0, 0});
        } else if (f.stage == 3) {
            f.r3 = final_result;
            int res = f.r1 + f.r2 - f.r3;
            if (str[f.i] == str[f.j]) {
                res++;
            }
            final_result = res;
            s.pop();
        }
    }

    return final_result;
}

