bool dfs(const string& pattern, int index, string& res, int state) {
    // Using an explicit stack since this is a backtracking search tree with multiple branches per node,
    // not a simple tail recursion.
    struct Frame {
        int index;
        int state;
        int d;
        bool is_increase;
    };

    std::stack<Frame> stk;

    // Helper lambda to initialize the loop/next state for a given index
    auto push_frame = [&](int idx, int curr_state) {
        if (idx == pattern.size()) return;
        bool inc = (pattern[idx] == 'I');
        int start_d = inc ? (res[idx] - '0' + 1) : 1;
        stk.push({idx, curr_state, start_d, inc});
    };

    if (index == pattern.size()) return true;
    push_frame(index, state);

    while (!stk.empty()) {
        auto& frame = stk.top();

        int idx = frame.index;
        int& d = frame.d;
        bool inc = frame.is_increase;
        int limit = inc ? 9 : (res[idx] - '0');

        bool found_next = false;
        while (d < limit) {
            int current_d = d;
            d++; // advance for future iterations if we backtrack

            if ((frame.state & (1 << current_d)) == 0) {
                res[idx + 1] = (char)('0' + current_d);
                int next_state = frame.state | (1 << current_d);

                if (idx + 1 == pattern.size()) {
                    return true;
                }

                push_frame(idx + 1, next_state);
                found_next = true;
                break;
            }
        }

        if (!found_next) {
            stk.pop();
        }
    }

    return false;
}

