bool dfs(const std::vector<int>& nums, int index, std::vector<int>& cur) {
    struct Frame {
        int index;
        int i;
    };

    if (nums.empty()) {
        for (int e : cur)
            if (e)
                return false;
        return true;
    }

    std::stack<Frame> stk;
    stk.push({index, 0});

    while (!stk.empty()) {
        auto& top = stk.top();

        if (top.index == nums.size()) {
            bool all_zero = true;
            for (int e : cur) {
                if (e) {
                    all_zero = false;
                    break;
                }
            }
            if (all_zero) {
                return true;
            }
            stk.pop();
            continue;
        }

        bool branched = false;
        while (top.i < cur.size()) {
            int i = top.i;
            top.i++;
            if (cur[i] >= nums[top.index]) {
                cur[i] -= nums[top.index];
                stk.push({top.index + 1, 0});
                branched = true;
                break;
            }
        }

        if (!branched) {
            stk.pop();
            if (!stk.empty()) {
                // Restore the state for the parent frame before trying the next branch
                auto& parent = stk.top();
                // parent.i - 1 corresponds to the index that was just tried
                int tried_i = parent.i - 1;
                cur[tried_i] += nums[parent.index - 1];
            }
        }
    }

    return false;
}

