    // subproblems at digit+1, converting it to a bottom-up iterative approach (or maintaining
    // the state via an explicit stack) is necessary. However, because this is a standard
    // DAG state-space where states at `digit` depend only on `digit+1`, a bottom-up
    // iterative loop from N down to 1 naturally eliminates recursion while preserving
    // the exact semantics and signature.

    // Initialize DP table with -1 if not already done externally, but assuming standard context:
    // Let's implement an iterative bottom-up approach to compute `dp[1][mask]` directly.

    // Base case layer: digit == N + 1
    // dp[N+1][mask] = (mask == (1<<10) - 1) ? 1 : 0
    for (int m = 0; m < (1<<10); ++m) {
        dp[N+1][m] = (m == (1<<10) - 1) ? 1 : 0;
    }

    // Iterate backwards from digit = N down to 1
    for (int d = N; d >= 1; --d) {
        for (int m = 0; m < (1<<10); ++m) {
            long long sum = 0;
            int start = (d == 1 && N > 1) ? 1 : 0; // matching 'if(digit==1) { for(int i = (N==1 ? 0 : 1); ...)'
            if (d == 1 && N == 1) {
                start = 0;
            }
            for (int i = start; i <= 9; ++i) {
                int next_mask = m | (1 << i);
                sum += dp[d + 1][next_mask];
            }
            dp[d][m] = sum;
        }
    }

    int initial_mask = 0;
    return dp[digit][mask];
}

