int steps(int source, int step, int dest) {
    if (abs(source) > dest) return INT_MAX;
    if (source == dest) return step;

    struct State {
        int source;
        int step;
        int pos;
        int neg;
        int phase;
    };

    stack<State> s;
    s.push({source, step, 0, 0, 0});
    int current_result = INT_MAX;

    while (!s.empty()) {
        State& curr = s.top();

        if (abs(curr.source) > dest) {
            current_result = INT_MAX;
            s.pop();
            if (!s.empty()) {
                if (s.top().phase == 1) s.top().pos = current_result;
                else if (s.top().phase == 2) s.top().neg = current_result;
            }
            continue;
        }

        if (curr.source == dest) {
            current_result = curr.step;
            s.pop();
            if (!s.empty()) {
                if (s.top().phase == 1) s.top().pos = current_result;
                else if (s.top().phase == 2) s.top().neg = current_result;
            }
            continue;
        }

        if (curr.phase == 0) {
            curr.phase = 1;
            s.push({curr.source + curr.step + 1, curr.step + 1, 0, 0, 0});
        } else if (curr.phase == 1) {
            curr.pos = current_result;
            curr.phase = 2;
            s.push({curr.source - curr.step - 1, curr.step + 1, 0, 0, 0});
        } else if (curr.phase == 2) {
            curr.neg = current_result;
            current_result = min(curr.pos, curr.neg);
            s.pop();
            if (!s.empty()) {
                if (s.top().phase == 1) s.top().pos = current_result;
                else if (s.top().phase == 2) s.top().neg = current_result;
            }
        }
    }

    return current_result;
}

