int minOperation(string& s, int i, int j, int count) {
    int n = s.size();
    // Size the memoization table dynamically based on string length and potential index ranges.
    // Since i goes from 0 to n and j goes from -1 to n-1, we use dimensions (n + 2) x (n + 2)
    // offset by +1 to safely handle j = -1.
    vector<vector<int>> memo(n + 2, vector<int>(n + 2, -1));

    auto solve = [&](auto& self, int cur_i, int cur_j, int cur_count) -> int {
        if ((cur_i >= n && cur_j < 0) || (cur_i == cur_j)) return MAX_VAL;
        if (cur_i < n && cur_j >= 0 && s[cur_i] == s[cur_j]) return cur_count;

        // Memoization key mapping: cur_j can be -1, so we shift by +1.
        int memo_j = cur_j + 1;
        if (memo_j >= 0 && memo_j < (int)memo[0].size() && cur_i >= 0 && cur_i < (int)memo.size()) {
            if (memo[cur_i][memo_j] != -1) {
                // The cached result represents the minimum steps *from* (cur_i, cur_j) to the base case,
                // relative to the current path's accumulated 'count'. We adjust by the difference in count.
                // However, to keep it simple and safe with varying 'count' parameters, we can memoize
                // the delta or ensure we pass a normalized state. Alternatively, pure DP from (i, j)
                // returning the base cost without initial 'count' is cleaner, but to strictly preserve
                // the exact signature and behavior, we memoize based on the remaining cost or state.
            }
        }

