        else if (cur_j < 0) return self(self, cur_i + 1, cur_j, cur_count + 1);
        else {
            return min(
                self(self, cur_i, cur_j - 1, cur_count + 1),
                self(self, cur_i + 1, cur_j, cur_count + 1)
            );
        }
    };

    return solve(solve, i, j, count);
}

