class node {
public:
    int data;
    node *left, *right;
};

// Since LISS (Largest Independent Set Size) for a tree requires computing 
// values for left and right subtrees in a branching manner (which can lead to 
// exponential recalculations, or require post-order traversal state), an 
// explicit std::stack using post-order traversal with memoization or a bottom-up 
// iterative approach is needed to completely eliminate recursion while preserving semantics.
#include <stack>
#include <unordered_map>

int LISS(node* root) {
    if (root == nullptr) return 0;

    // Using post-order traversal via an explicit stack to compute LISS iteratively.
    // We store the computed LISS values for each node in a hash map.
    std::stack<node*> s1, s2;
    std::unordered_map<node*, int> liss_map;

    s1.push(root);
    while (!s1.empty()) {
        node* curr = s1.top();
        s1.pop();
        s2.push(curr);

        if (curr->left) s1.push(curr->left);
        if (curr->right) s1.push(curr->right);
    }

    while (!s2.empty()) {
        node* curr = s2.top();
        s2.pop();

        int size_excl = 0;
        if (curr->left) size_excl += liss_map[curr->left];
        if (curr->right) size_excl += liss_map[curr->right];

        int size_incl = 1;
        if (curr->left) {
            if (curr->left->left) size_incl += liss_map[curr->left->left];
            if (curr->left->right) size_incl += liss_map[curr->left->right];
        }
        if (curr->right) {
            if (curr->right->left) size_incl += liss_map[curr->right->left];
            if (curr->right->right) size_incl += liss_map[curr->right->right];
        }

        liss_map[curr] = max(size_incl, size_excl);
    }

    return liss_map[root];
}

