int eval(node* root) {
    if (!root) return 0;

    stack<node*> s;
    stack<int> vals;
    node* curr = root;
    node* lastVisited = nullptr;

    while (curr || !s.empty()) {
        while (curr) {
            s.push(curr);
            curr = curr->left;
        }

        curr = s.top();

        if (!curr->left && !curr->right) {
            vals.push(toInt(curr->info));
            s.pop();
            lastVisited = curr;
            curr = nullptr;
        } else if (curr->right && lastVisited != curr->right) {
            curr = curr->right;
        } else {
            s.pop();
            int r_val = vals.top(); vals.pop();
            int l_val = vals.top(); vals.pop();

            int res = 0;
            if (curr->info == " + ") res = l_val + r_val;
            else if (curr->info == " - ") res = l_val - r_val;
            else if (curr->info == " * ") res = l_val * r_val;
            else res = l_val / r_val;

            vals.push(res);
            lastVisited = curr;
            curr = nullptr;
        }
    }

    return vals.empty() ? 0 : vals.top();
}

