#include <string>
#include <algorithm>
#include <climits>
#include <iostream>
#include <stack>

using namespace std;

bool check(const string& S) {
    for(size_t i = 1; i < S.length(); ++i) {
        if(S[i-1] == S[i]) {
            return false;
        }
    }
    return true;
}

void minimumSwaps(string& S, int& ansSwaps, int swaps = 0, int idx = 0) {
    struct State {
        int idx;
        int i;
        int j;
        int swaps;
        int phase;
    };

    stack<State> st;
    st.push({idx, idx, idx + 1, swaps, 0});

    while (!st.empty()) {
        State& curr = st.top();

        if (curr.phase == 0) {
            if (check(S)) {
                ansSwaps = min(ansSwaps, curr.swaps);
            }
            curr.i = curr.idx;
            curr.phase = 1;
        }

        if (curr.phase == 1) {
            if (curr.i < (int)S.length()) {
                curr.j = curr.i + 1;
                curr.phase = 2;
            } else {
                st.pop();
                continue;
            }
        }

        if (curr.phase == 2) {
            if (curr.j < (int)S.length()) {
                swap(S[curr.i], S[curr.j]);
                // Push next recursive state
                st.push({curr.i + 1, curr.i + 1, curr.i + 2, curr.swaps + 1, 0});
                // Change current state phase to handle backtrack after child returns
                curr.phase = 3;
                continue;
            } else {
                curr.i++;
                curr.phase = 1;
                continue;
            }
        }

        if (curr.phase == 3) {
            // Backtrack the swap made before pushing child
            swap(S[curr.i], S[curr.j]);
            curr.j++;
            curr.phase = 2;
            continue;
        }
    }
}

void findMinimumSwaps(string& S) {
    int ansSwaps = INT_MAX;
    minimumSwaps(S, ansSwaps);
    if(ansSwaps == INT_MAX) cout << "-1";
    else cout << ansSwaps;
}

