int seriesSum(int calculated, int current, int N) {
    int total_sum = 0;
    int i;
    while (current <= N) {
        int cur = 1;
        int next_calculated = calculated + current;
        for (i = calculated; i < next_calculated; ++i) {
            cur *= i;
        }
        total_sum += cur;
        calculated = next_calculated;
        current += 1;
    }
    return total_sum;
}

