TreeNode* dfs(const vector<int>& v, int l, int r){

        if(l > r || l >= v.size() || r >= v.size()) return NULL;

        TreeNode* root = new TreeNode(v[l]);

        int i;
        for(i = l + 1; i <= r; i ++)
