TreeNode* dfs(const vector<int>& v, int l, int r){
        TreeNode* dummyHead = nullptr;
        TreeNode** currentRootPtr = &dummyHead;

        struct Frame {
            int l, r;
            TreeNode** parentLink;
        };

        std::stack<Frame> stack;
        stack.push({l, r, currentRootPtr});

        while(!stack.empty()) {
            Frame frame = stack.top();
            stack.pop();

            int cur_l = frame.l;
            int cur_r = frame.r;

            if(cur_l > cur_r || cur_l >= (int)v.size() || cur_r >= (int)v.size()) {
                *(frame.parentLink) = nullptr;
                continue;
            }

            TreeNode* root = new TreeNode(v[cur_l]);
            *(frame.parentLink) = root;

            int i;
            for(i = cur_l + 1; i <= cur_r; i ++)
                if(v[i] > v[cur_l]) break;

            // Push right child first so left child is processed first
            stack.push({i, cur_r, &(root->right)});
            stack.push({cur_l + 1, i - 1, &(root->left)});
        }

        return dummyHead;
    }
